package com.bqsqwad.heartbreakhealer.feature.entertainment

/** Five complete, original ten-part serials with satisfying conclusions. */
internal object StoryLibraryBatch6 {
    val stories = listOf(
        StorySeries("the_winter_garden", "The Winter Garden", "A school caretaker and a curious student restore a greenhouse and uncover the history of its first gardeners.", listOf(
            StoryPart(1, "Frosted Glass", listOf("On a cold Monday, Sade noticed a warm glow inside the school's locked greenhouse. The caretaker explained that the heating had been switched off years ago, yet one corner still held a little warmth.", "A small plaque named the greenhouse after a former science teacher, Mrs Aina. Sade asked why it had been closed.")),
            StoryPart(2, "The Caretaker's Key", listOf("The caretaker found an old maintenance notebook. It recorded a leak, a broken vent, and a request for repairs that had never been approved.", "The final page mentioned a set of planting journals kept by the school's first garden club. Their location was marked only as 'near the winter roses'.")),
            StoryPart(3, "The Rose Labels", listOf("Sade found faded plant labels beneath a bench. Each carried a student's initials and a year, showing that many classes had cared for the greenhouse.", "One label had a note asking the next club to look after a packet of seeds stored in the library.")),
            StoryPart(4, "The Seed Packet", listOf("The librarian located the packet inside a gardening book. It was labelled with the name of a local flower and a note from Mrs Aina explaining that the seeds should be planted only after the greenhouse was repaired.", "Sade showed the note to her science teacher, who agreed to request a professional inspection before any work began.")),
            StoryPart(5, "A Safe Plan", listOf("The inspection found that the greenhouse frame was sound but the vent and water system needed repair. The school approved a modest project and asked the students to prepare a maintenance plan.", "Sade's team listed tasks that students could safely do and tasks that required qualified adults. They also planned a watering rota for school holidays.")),
            StoryPart(6, "The Old Garden Club", listOf("A former student, now a horticulturist, visited and shared photographs of the greenhouse in its busiest years. She recognised the seed packet and explained that Mrs Aina had collected plants from local gardens.", "She offered to help identify the seeds and teach the club how to keep records of each plant's origin.")),
            StoryPart(7, "The First Planting", listOf("After repairs were completed, the club planted the seeds in suitable containers under adult supervision. They labelled every tray and recorded the date and conditions.", "Some seedlings appeared later than expected. Instead of giving up, the students checked the notes and learned that different seeds needed different periods to germinate.")),
            StoryPart(8, "A Holiday Problem", listOf("The school calendar showed a long break approaching. Sade worried that the seedlings would be neglected, so the club arranged a supervised care rota with staff and volunteers.", "The horticulturist helped them prepare clear instructions and an emergency contact list. The plan made it possible for the garden to continue without relying on one person.")),
            StoryPart(9, "The Greenhouse Open Day", listOf("At the open day, families saw the restored greenhouse and the students' growing records. The former student brought a photograph of Mrs Aina standing beside the same flower now growing in the new trays.", "The headteacher announced that the greenhouse would remain a permanent science space, with yearly maintenance reviews and a student handover notebook.")),
            StoryPart(10, "A Garden for Every Season", listOf("Sade placed the original seed packet in a display case and wrote the first entry in the new garden journal. The greenhouse was no longer a locked room; it had become a working classroom.", "The first flowers opened just before the term ended. Sade understood that the real inheritance was not the seeds alone, but the careful knowledge, shared responsibility, and patience that allowed something living to flourish again."))
        )),
        StorySeries("the_postcard_project", "The Postcard Project", "A class project reconnects an isolated island school with the people who once studied there.", listOf(
            StoryPart(1, "A Card from the Island", listOf("During a lesson about local history, Musa found a postcard showing a small island school. The message on the back read, 'Tell the next class we are still learning.'", "His teacher said the school had closed when families moved to the mainland, but the building still stood and was occasionally used by fishermen.")),
            StoryPart(2, "The Old Register", listOf("The school archive contained a register with names and addresses of former pupils. Musa's class decided to write to them, using the school office to protect private contact details.", "The first reply came from a retired nurse who remembered the island school as the place where she learned to read.")),
            StoryPart(3, "Many Different Memories", listOf("More replies arrived. Some remembered lessons under a tree, others remembered the boat journey to class. A few recalled that the school had struggled to get books and supplies.", "Musa's class realised there was no single version of the past. They asked each person for permission before including their memories in a display.")),
            StoryPart(4, "The Missing Photograph", listOf("One former pupil mentioned a class photograph that had disappeared during the move. She believed it had been left in a storage chest at the old building.", "The local council arranged a supervised visit with a caretaker. The students found the chest, but it held only lesson plans and a bundle of postcards.")),
            StoryPart(5, "A Message in the Bundle", listOf("The postcards were written by pupils to a teacher who had moved away. They described a reading club and a plan to create a small library for the island.", "One card said the books had been packed for transfer, but no record showed where they went. Musa asked the mainland library whether it had received them.")),
            StoryPart(6, "The Library's Ledger", listOf("The librarian found a delivery ledger listing several boxes from the island school. The books had been added to the library collection but were never labelled as a separate donation.", "The librarian offered to create a display acknowledging the school and invited former pupils to help identify the books.")),
            StoryPart(7, "A Day of Stories", listOf("The class hosted a video gathering with former pupils. They shared memories, identified old photographs, and explained which books had mattered most to them.", "A former teacher joined and described how the reading club had helped students prepare for secondary school. The class recorded the conversation only with everyone's agreement.")),
            StoryPart(8, "The Island Visit", listOf("A small group of students visited the island with their teacher and local guides. They found the old school building in need of repairs, so they did not enter unsafe areas.", "Outside, they placed a weatherproof plaque explaining the school's history and the route by which its books had reached the mainland library.")),
            StoryPart(9, "A New Reading Link", listOf("The mainland library created a monthly island reading day at a community centre, using books selected with local families. Former pupils helped fund transport and donated new titles.", "Musa's class prepared a travelling display of postcards and photographs. The project connected the school's past to a practical service in the present.")),
            StoryPart(10, "The Next Postcard", listOf("At the end of term, Musa wrote a postcard to the island school, even though no class met there anymore. He described the reading day and thanked the former pupils who had answered.", "The card was placed beside the original one in the library display. The old school had not reopened, but its learning community had found a new way to continue. Musa had discovered that a message can travel far beyond the place where it begins."))
        )),
        StorySeries("the_courtyard_chessboard", "The Courtyard Chessboard", "A worn chessboard brings neighbours together and helps settle a long-running disagreement fairly.", listOf(
            StoryPart(1, "The Board Under the Stairs", listOf("During a community centre clean-up, Kola found a large wooden chessboard with several missing pieces. A label said it had belonged to a weekly neighbourhood club.", "The centre manager remembered that the club stopped after a disagreement about who owned the board. Nobody had used it for years.")),
            StoryPart(2, "The Club Photograph", listOf("An old photograph showed players gathered around the board. The names on the back included two families who still lived nearby, though they rarely spoke.", "Kola asked his chess coach to help identify the people before making assumptions about the disagreement.")),
            StoryPart(3, "Two Versions", listOf("One family believed the board had been donated to the centre. The other believed it had been loaned for a tournament and never returned.", "The centre's donation ledger listed a chess set but did not mention the board. Kola realised that the records were incomplete.")),
            StoryPart(4, "The Tournament Programme", listOf("The library archive held a programme from the final tournament. It described the board as a community project made by a local carpenter and funded by small contributions from both families.", "The programme named the carpenter, who had moved away, and included a note that the board should remain at the centre for public use.")),
            StoryPart(5, "The Carpenter's Receipt", listOf("The carpenter's daughter found his receipt book. It confirmed that the board was built for the centre and that both families had contributed to its construction.", "She also found a letter thanking the families for helping create a place where young people could learn chess together.")),
            StoryPart(6, "A Missing Piece", listOf("The receipt book listed a complete set of pieces, but the centre had only half. The caretaker remembered that the missing pieces had been placed in a tin after a roof leak.", "The tin was found in a dry storage cupboard. The pieces were intact, and a local craft teacher offered to repair the board's surface.")),
            StoryPart(7, "The Repair Day", listOf("The two families were invited to help restore the board. At first they were awkward, but the carpenter's letter gave them a shared point of reference.", "They agreed that the board belonged to the community centre and that both families had helped make it possible. Each apologised for repeating a version of the story without checking the records.")),
            StoryPart(8, "A New Club", listOf("Kola and his coach organised a new chess club with beginner lessons and a schedule that gave everyone a turn. The centre published clear rules for borrowing and caring for the set.", "The first session included children, parents, and older residents. The two families sat at the same table and played a friendly match.")),
            StoryPart(9, "The Annual Match", listOf("The centre announced an annual community chess day in honour of the carpenter. The repaired board was used for the opening match, while a copy of the original programme was displayed nearby.", "The event raised enough money to buy additional sets so beginners would not have to wait for a turn.")),
            StoryPart(10, "A Game Shared", listOf("Kola placed a small plaque beside the board listing the carpenter and the community contributors. The old disagreement had been resolved through evidence, conversation, and a clear agreement.", "As the club filled the courtyard with friendly matches, Kola saw that the best part of chess was not winning a game. It was learning to think carefully, respect an opponent, and make room for another person at the board."))
        )),
        StorySeries("the_bridge_of_names", "The Bridge of Names", "A student historian helps restore the names of the people who built a beloved neighbourhood bridge.", listOf(
            StoryPart(1, "Names in the Stone", listOf("A plaque beside the footbridge listed the date it opened but no names of the workers. When the plaque cracked, the council planned to replace it with an identical one.", "Student historian Bisi wondered why the bridge's builders had never been recorded. Her grandfather said a group of local craftspeople had worked on it after a major flood.")),
            StoryPart(2, "The Newspaper Photograph", listOf("Bisi searched the library and found a newspaper photograph of the opening ceremony. Several workers stood behind the mayor, but the caption named only the officials.", "The photograph's negative had been donated to the archive by a reporter. The archivist offered to help identify the people if Bisi could find other records.")),
            StoryPart(3, "The Payroll Book", listOf("The council archive held an old payroll book listing workers by initials and trade. It was difficult to match the names to faces, but the dates aligned with the bridge construction.", "Bisi asked retired residents whether they recognised any of the initials. Several families brought photographs and letters.")),
            StoryPart(4, "The Mason's Notebook", listOf("A retired mason's notebook described the work and named apprentices who had helped shape the bridge stones. It also recorded that some workers were paid through a cooperative.", "The cooperative's records had moved to a local history society. Bisi arranged a supervised visit to review the documents.")),
            StoryPart(5, "The Cooperative List", listOf("The society found a membership list with full names and addresses. It confirmed that the bridge had been built by a mixed team of trained craftspeople and apprentices from the neighbourhood.", "One name appeared in several documents but was missing from the payroll book. Bisi wondered whether the person had volunteered.")),
            StoryPart(6, "The Volunteer Who Taught", listOf("The missing name belonged to a retired teacher who had helped train young workers in reading plans and measuring materials. His family shared a letter describing the bridge project as a community learning effort.", "Bisi added the letter to the evidence folder and asked the archive to verify every name before publication.")),
            StoryPart(7, "Checking Every Letter", listOf("The archivist compared the photographs, payroll, cooperative list, and family letters. Two spellings needed correction, and one person asked that their address remain private.", "Bisi learned that public recognition did not require publishing personal details. The project would list names and roles only after family confirmation.")),
            StoryPart(8, "A Plaque Rewritten", listOf("The council approved a new plaque listing the confirmed builders, apprentices, and the teacher who helped train them. It also included a note that the bridge had been repaired and inspected over the years by later teams.", "Families reviewed the wording and agreed that the plaque should recognise collective effort rather than rank contributors.")),
            StoryPart(9, "The Unveiling", listOf("At the unveiling, residents read the names aloud. Several families met for the first time, comparing photographs and remembering people whose work had shaped the neighbourhood.", "The council gave the archive copies of the verified records and promised to preserve them with the bridge maintenance documents.")),
            StoryPart(10, "The Bridge Remembers", listOf("Bisi's school created a local history project based on the research, teaching students how to verify sources and ask families for consent. The bridge remained a practical crossing, but its story was now visible to everyone who used it.", "Bisi's grandfather stood beside the new plaque and found his old mentor's name. The project had not changed the bridge's stones; it had changed what the community knew about the hands that placed them. The record was accurate, the families had been heard, and the bridge could carry both people and memory."))
        )),
        StorySeries("the_last_seed_library", "The Last Seed Library", "A young gardener and a librarian save a collection of local seeds by building a careful community archive.", listOf(
            StoryPart(1, "A Tin on the Shelf", listOf("Ayo found a small tin of seeds behind the library's gardening books. A label said they had been collected from local gardens, but the collection date was more than twenty years old.", "The librarian explained that the seed library had once helped residents share plants suited to the local climate. It had closed when its volunteer coordinator moved away.")),
            StoryPart(2, "The Coordinator's Address", listOf("An old newsletter listed the coordinator as Mrs Ekanem. The librarian contacted her through the community association, and she agreed to visit.", "Mrs Ekanem said the seeds were valuable only if their origins and storage conditions were understood. She warned Ayo not to plant unknown seeds before identifying them.")),
            StoryPart(3, "The Seed Records", listOf("The tin included a few handwritten labels, but many were faded. Mrs Ekanem showed Ayo how to compare the records with photographs and ask contributors' families for confirmation.", "They discovered that some seeds came from gardens that no longer existed. Their stories were as important as their names.")),
            StoryPart(4, "The Garden Families", listOf("Ayo and the librarian contacted several families. One recognised a seed variety from a garden that had supplied vegetables to neighbours during a difficult season.", "Another family had kept a notebook describing how the plants grew and which conditions suited them. They agreed to donate a copy to the archive.")),
            StoryPart(5, "A Safe Catalogue", listOf("The school science teacher helped design a catalogue with verified names, collection dates, and storage notes. Unidentified seeds were marked clearly rather than guessed.", "The team decided that any planting would be supervised and that seeds would be shared only when their identity and handling needs were known.")),
            StoryPart(6, "The Community Plot", listOf("The council offered a small community plot for a trial garden. A horticulture volunteer checked the soil and helped choose suitable containers and growing areas.", "Ayo's team prepared a budget, a watering rota, and a plan for school holidays. The project would begin with a few identified varieties.")),
            StoryPart(7, "The First Growth", listOf("The first plants grew slowly. Students recorded germination dates, leaf changes, and watering conditions, comparing them with the old notebook.", "One variety did not grow, and the team documented the result instead of pretending every seed had succeeded. Mrs Ekanem said honest records would help future gardeners.")),
            StoryPart(8, "A New Donation", listOf("A family donated a fresh batch of seeds from a garden they had maintained for generations. They provided photographs and written permission for the history to be shared.", "The seed library added the new collection with clear labels and a note explaining how the seeds had been passed down.")),
            StoryPart(9, "The Open Seed Day", listOf("The library hosted a seed-sharing day where residents could learn about the collection and contribute verified local varieties. Volunteers explained that not every seed was suitable for every garden.", "Ayo displayed the original tin beside the new catalogue. Visitors could see how a small collection had become a carefully maintained community resource.")),
            StoryPart(10, "A Living Archive", listOf("The seed library reopened with a volunteer team, a storage schedule, a growing log, and a yearly review. The old tin was preserved as part of the collection's history rather than used for everyday storage.", "Ayo added one final note: 'A seed is a beginning, not a guarantee.' The project had saved the collection by treating it with care, respecting the families who shared it, and recording what they learned. The garden would keep growing, and the library now had a plan to help it last."))
        ))
    )
}
